// Initialize client tracking in flow context
let clients = flow.get('clients') || {};
const now = new Date();

// Parse incoming message
const clientData = msg.payload;
const clientId = clientData.client_id || clientData.hostname;
const status = clientData.status; // 'online' or 'offline'

if (status === 'online') {
    // Client came online
    clients[clientId] = {
        hostname: clientData.hostname,
        client_id: clientId,
        ip_address: clientData.ip_address,
        last_seen: now.toISOString(),
        status: 'online',
        first_seen: clients[clientId]?.first_seen || now.toISOString()
    };

    node.status({fill: "green", shape: "dot", text: `${Object.keys(clients).length} clients online`});

} else if (status === 'offline') {
    // Client went offline
    if (clients[clientId]) {
        delete clients[clientId];
    }

    node.status({fill: "yellow", shape: "dot", text: `${Object.keys(clients).length} clients online`});
}

// Save updated client list
flow.set('clients', clients);

// Prepare output for automation logic
msg.payload = {
    client_id: clientId,
    status: status,
    active_clients: Object.keys(clients),
    client_count: Object.keys(clients).length,
    timestamp: now.toISOString(),
    clients: clients
};

return msg;

// Update last seen timestamp for heartbeat
let clients = flow.get('clients') || {};
const now = new Date();

const clientData = msg.payload;
const clientId = clientData.client_id || clientData.hostname;

if (clients[clientId]) {
    clients[clientId].last_seen = now.toISOString();
    clients[clientId].uptime = clientData.uptime;
    flow.set('clients', clients);
}

// Update UI
msg.payload = {
    clients: clients,
    client_count: Object.keys(clients).length,
    timestamp: now.toISOString()
};

return msg;

// Detect when we go from 0 to 1+ clients or 1+ to 0 clients
const clientCount = msg.payload.client_count;
const status = msg.payload.status;
const clientId = msg.payload.client_id;

let previousCount = flow.get('previous_client_count') || 0;
flow.set('previous_client_count', clientCount);

const activityLog = flow.get('activity_log') || [];

// Trigger automation events
if (previousCount === 0 && clientCount > 0) {
    // First client came online - trigger server boot
    const timestamp = msg.payload.timestamp || new Date().toISOString();

    // Log the trigger event
    activityLog.unshift({
        timestamp: timestamp,
        action: 'Trigger',
        type: 'client_online',
        trigger: `First client connected: ${clientId}`,
        status: 'detected'
    });
    if (activityLog.length > 50) activityLog.pop();
    flow.set('activity_log', activityLog);

    msg.payload = {
        event: 'first_client_online',
        client_id: clientId,
        client_count: clientCount,
        timestamp: timestamp
    };
    node.status({fill: "green", shape: "dot", text: "First client online"});
    return [msg, null];

} else if (previousCount > 0 && clientCount === 0) {
    // Last client went offline - trigger server shutdown (with grace period)
    const timestamp = msg.payload.timestamp || new Date().toISOString();

    // Log the trigger event
    activityLog.unshift({
        timestamp: timestamp,
        action: 'Trigger',
        type: 'client_offline',
        trigger: `Last client disconnected: ${clientId}`,
        status: 'detected'
    });
    if (activityLog.length > 50) activityLog.pop();
    flow.set('activity_log', activityLog);

    msg.payload = {
        event: 'last_client_offline',
        client_id: clientId,
        client_count: clientCount,
        timestamp: timestamp
    };
    node.status({fill: "yellow", shape: "dot", text: "Last client offline"});
    return [null, msg];

} else {
    // No state change
    node.status({fill: "blue", shape: "dot", text: `${clientCount} clients`});
    return [null, null];
}

// Grace period for heartbeats
const GRACE_PERIOD = 150;
let clients = flow.get('clients') || {};
const now = new Date();
let removedCount = 0;
let lastRemovedId = '';

for (const clientId in clients) {
    const lastSeen = new Date(clients[clientId].last_seen);
    if ((now - lastSeen) / 1000 > GRACE_PERIOD) {
        lastRemovedId = clientId;
        delete clients[clientId];
        removedCount++;
    }
}

const initialized = context.get('initialized') || false;
if (removedCount > 0 || !initialized) {
    flow.set('clients', clients);
    context.set('initialized', true);
    msg.payload = {
        client_id: lastRemovedId || 'system',
        status: removedCount > 0 ? 'offline' : 'sync',
        active_clients: Object.keys(clients),
        client_count: Object.keys(clients).length,
        timestamp: now.toISOString(),
        clients: clients
    };
    node.status({fill: removedCount > 0 ? "red" : "blue", shape: "dot", text: `Ready (${Object.keys(clients).length} active)`});
    return [msg, msg];
}
return null;
